    used_diffs = set()

    def get_triangle_diffs(a, b, c):
        return sorted([abs(a-b), abs(a-c), abs(b-c)])

    def backtrack_clique(g):
        if g == 6:
            return len(used_diffs) == 33

        # Try to assign 3 labels to clique g
        available = [l for l in range(34) if l not in used_labels]

        if g == 0:
            # First clique: try some random triples
