                a, b, c = triple
                diffs = get_triangle_diffs(a, b, c)
                if len(set(diffs)) == 3 and all(d > 0 for d in diffs):
                    # Try all 6 permutations
                    for perm in [(0,1,2), (0,2,1), (1,0,2), (1,2,0), (2,0,1), (2,1,0)]:
                        labels[0], labels[1], labels[2] = triple[perm[0]], triple[perm[1]], triple[perm[2]]
                        used_labels.update(triple)
                        for d in diffs:
                            used_diffs.add(d)

