# Better backtracking with clique-by-clique assignment
def solve():
    random.seed(42)

    labels = [None] * n_vertices
    used_labels = set()
    used_diffs = set()

    def backtrack_clique(g):
        if g == 6:
            return len(used_diffs) == n_edges

        available = sorted([l for l in range(max_label + 1) if l not in used_labels])

        if g == 0:
            # First clique: try all combinations of 3 labels
            for combo in itertools.combinations(range(max_label + 1), 3):
                for perm in itertools.permutations(combo):
                    # Check triangle
                    d01, d02, d12 = abs(perm[0]-perm[1]), abs(perm[0]-perm[2]), abs(perm[1]-perm[2])
                    if d01 == 0 or d02 == 0 or d12 == 0:
                        continue
                    if len({d01, d02, d12}) != 3:
                        continue

                    labels[0], labels[1], labels[2] = perm
                    used_labels.update(combo)
                    used_diffs.update([d01, d02, d12])

                    if backtrack_clique(1):
                        return True

                    used_labels.difference_update(combo)
                    used_diffs.difference_update([d01, d02, d12])
            return False
        else:
            prev = [labels[(g-1)*3 + i] for i in range(3)]

